/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useContext,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  interpolate,
  Sequence,
  type SequenceControls,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

const { fontFamily: SANS } = loadInter("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// ---------------------------------------------------------------------------
// Proportions
//
// Every constant below is a *fraction* of the composition, never a pixel, so
// the scene holds its shape at 720p, 1080p or a vertical crop. They were
// measured off a reference recording at 802x450 by sub-pixel edge integration
// and divided through; the comment on each names what was measured.
// ---------------------------------------------------------------------------

/**
 * Pill height as a multiple of the act-1 type size. Measured 44.21px against an
 * implied 39.2px em, both at 450.
 *
 * Keyed to the type rather than to the frame so that when a long status forces
 * the line to shrink, the pill shrinks with it instead of turning into a slab
 * with a small word floating in it.
 */
const PILL_H = 1.128;
/**
 * Corner radius as a fraction of the pill's own height.
 *
 * Not a stadium. Fitting a circle to the sub-pixel left edge over the pill's
 * top 12 rows gives R/h = 0.222–0.235 at rms 0.07–0.17px; R = h/2 fits the same
 * rows at rms 6.9–7.7px, two orders of magnitude worse. A stadium here reads as
 * a completely different object — it is the single easiest detail to get wrong.
 */
const PILL_R = 0.229;
/** Pill padding either side of the label, as a fraction of pill height. */
const PILL_PAD = 0.19;
/** Prefix-to-pill gap, as a fraction of pill height. Measured 6.5px of 44.2. */
const PILL_GAP = 0.147;
/** Act-1 type size, as a fraction of frame height. Cap 29px / 0.72em of 450. */
const ACT1_EM = 0.087;
/** Act-2 type size, as a fraction of frame height. Cap 72px / 0.72em of 450. */
const ACT2_EM = 0.222;
/** Chip padding, as a fraction of its own type size. */
const CHIP_PAD_X = 0.42;
const CHIP_PAD_Y = 0.165;
/** Chip corner radius and hairline, as fractions of chip height. */
const CHIP_R = 0.162;
const CHIP_BORDER = 0.017;
/** Chip margin from the frame edge, as a fraction of frame width. */
const CHIP_INSET = 0.04;
/** Share of the frame width the act-1 lockup may occupy before it is scaled. */
const ACT1_FIT = 0.92;
/** Gap between stacked chips, as a fraction of frame height. */
const CHIP_GAP = 0.057;

/**
 * The width morph is a **cubic-bezier, not a spring** — the `y2 > 1` control
 * value is the overshoot.
 *
 * This is not a stylistic preference. Fitting Remotion's `spring()` over a full
 * (damping, stiffness, rest) grid lands at rms 19.6px on a 207px travel, and the
 * failure is structural: a spring released from rest is at pi^2/242 = 4.1% of
 * travel one frame into an eleven-frame rise, and the reference is at 0.65%. No
 * triple is six times flatter at the start and still peaks that early. Fitted
 * per morph the reference gives (0.6,0,0.3,1.8) and (0.7,0.4,0.3,1.3); this is
 * their average, at rms 1.1–1.7% of travel.
 */
const WIDTH_EASE = Easing.bezier(0.65, 0.2, 0.3, 1.5);
/** Seconds the width morph runs. Measured 15 and 14 frames on a 24fps clock. */
const WIDTH_SECONDS = 0.6;

/**
 * The label roll: a symmetric ease-in-out — deliberately gentler and longer than
 * the reference.
 *
 * The reference rolls in 8 frames of 24fps on (0.75, 0, 0.25, 1) (measured
 * progress 0.010, 0.053, 0.164, 0.499, 0.833, 0.946, 0.990, 1.000). Rendered at
 * 30fps that is 10 frames whose middle two each move a third of the travel —
 * 32px a frame at 1080p — so the frame between them shows two half-cut labels and
 * the swap reads as a flicker, not a roll. Reported as "flipping too fast".
 *
 * (0.45, 0, 0.55, 1) over 0.5s is 15 frames at 30: no step above 13px at 1080p,
 * none below 0.8px (so no frozen frames in the tails, motion-quality rule 0).
 * 0.6s was tried first and read as too slow; 0.5s is the step between the two.
 * The label lands three frames before the width morph finishes its overshoot.
 */
const ROLL_EASE = Easing.bezier(0.45, 0, 0.55, 1);
/** Seconds the roll runs. See ROLL_EASE for why it is not the reference's 1/3. */
const ROLL_SECONDS = 0.5;
/** Roll travel, as a multiple of pill height. Measured 47.1px on a 46.2 pill. */
const ROLL_TRAVEL = 1.02;

/** Seconds the green-to-cream crossfade takes. Measured 18 frames of 60fps. */
const FADE_SECONDS = 0.3;
/** Seconds the lockup takes to leave upward. Measured 0.19s, exponential. */
const EXIT_SECONDS = 0.2;
/** Time constant of the act-2 scroll step, in seconds. Fitted 1-exp(-t/tau). */
const SCROLL_TAU = 0.06;

/**
 * The per-letter intro scale.
 *
 * Measured peak is 1.45x the settled size, and a spring's overshoot is
 * `exp(-pi*zeta/sqrt(1-zeta^2))` — so zeta = 0.25, which at stiffness 100 and
 * mass 1 is damping 5. That is where these numbers come from; they are not a
 * taste setting, and changing the damping moves the peak off the reference.
 */
const LETTER_SPRING = { damping: 5, stiffness: 100, mass: 1 } as const;

/**
 * Pure scheduling and fitting math. Everything above the component is
 * frame-deterministic and side-effect free so it can be unit tested.
 */

/** Accepts an array or the comma-separated string the customizer passes. */
function toList(value?: string[] | string): string[] {
  const list = typeof value === "string" ? value.split(",") : (value ?? []);
  return list.map((s) => s.trim()).filter(Boolean);
}

/**
 * Exponential ease-out, in frames.
 *
 * The reference's scroll step is not any fixed-duration curve: easeOutCubic
 * predicts 0.977 at t=0.167s against a measured 0.918, and quint/expo are far
 * too fast at the head. `1 - exp(-t/tau)` fits every sample of every step at
 * tau = 0.060s, which is what a lerp-toward-target does, and it never overshoots
 * — the reference's peak progress is exactly 1.000 at every step.
 */
function settle(frames: number, tau: number): number {
  if (frames <= 0) return 0;
  return 1 - Math.exp(-frames / tau);
}

/**
 * Which status is up at `frame`, and how many frames since it arrived.
 *
 * The index only ever advances, and `since` is relative to the swap that put
 * the current label up — so a swap still settling when the next one starts
 * hands over cleanly instead of compounding.
 */
function statusAt({
  frame,
  introFrames,
  statusHold,
  count,
}: {
  frame: number;
  introFrames: number;
  statusHold: number;
  count: number;
}): { index: number; since: number } {
  if (count <= 0) return { index: 0, since: 0 };
  let index = 0;
  for (let i = 1; i < count; i += 1) {
    if (frame >= introFrames + (i - 1) * statusHold) index = i;
  }
  return { index, since: frame - (introFrames + (index - 1) * statusHold) };
}

/**
 * How many chips have arrived at `frame`, and how far the step they triggered
 * has run. Clamped to `count`, so the field stops stepping once the last chip
 * is in rather than scrolling the whole column off the top.
 */
function chipAt({
  frame,
  beat,
  stagger,
  count,
}: {
  frame: number;
  beat: number;
  stagger: number;
  count: number;
}): { arrived: number; since: number } {
  if (count <= 0 || frame < beat) return { arrived: 0, since: 0 };
  const arrived = Math.min(count, Math.floor((frame - beat) / stagger) + 1);
  return { arrived, since: frame - beat - (arrived - 1) * stagger };
}

/**
 * How much a measured line has to shrink to sit inside its budget.
 *
 * Only ever <= 1. Scaling *up* to fill the budget would make a two-word status
 * larger than a five-word one, which is the opposite of a design system.
 */
function fitScale(measured: number, budget: number): number {
  if (!(measured > 0) || !(budget > 0)) return 1;
  return Math.min(1, budget / measured);
}

export interface StatusCycleMotion {
  /** Easing of the pill's width. `y2 > 1` on a bezier is what gives overshoot. */
  widthEase: (t: number) => number;
  /** Seconds the width morph runs. */
  widthSeconds: number;
  /** Easing of the label roll. */
  rollEase: (t: number) => number;
  /** Seconds the roll runs. */
  rollSeconds: number;
  /** Roll travel, as a multiple of pill height. */
  rollTravel: number;
  /** Seconds the field crossfade takes. */
  fadeSeconds: number;
  /** Seconds the lockup takes to leave upward. */
  exitSeconds: number;
  /** Time constant of an act-2 scroll step, in seconds. */
  scrollTau: number;
  /** Spring the intro's per-letter scale runs on. Damping sets the peak. */
  letterSpring: { damping: number; stiffness: number; mass: number };
  /** Frames between one letter's entry and the next. */
  letterStagger: number;
}

/**
 * Measured defaults. Every one but the roll is fitted from frame data — see the
 * constant it reads from — so overriding one is a deliberate departure, not a
 * tweak. The roll departs from its reference on purpose; ROLL_EASE says why.
 */
const STATUS_CYCLE_MOTION: StatusCycleMotion = {
  widthEase: WIDTH_EASE,
  widthSeconds: WIDTH_SECONDS,
  rollEase: ROLL_EASE,
  rollSeconds: ROLL_SECONDS,
  rollTravel: ROLL_TRAVEL,
  fadeSeconds: FADE_SECONDS,
  exitSeconds: EXIT_SECONDS,
  scrollTau: SCROLL_TAU,
  letterSpring: LETTER_SPRING,
  letterStagger: 1,
};

export interface StatusCycleProps {
  /** The line that does not change, to the left of the pill. */
  prefix?: string;
  /** Pill labels, in order. Also accepts a comma-separated string. */
  statuses?: string[] | string;
  /** Act-2 chip labels, in order. Also accepts a comma-separated string. */
  chips?: string[] | string;
  /** Act-1 field. Defaults to the design system's `primary`. */
  fieldColor?: string;
  /** Act-2 field. Defaults to the design system's `background`. */
  pageColor?: string;
  /** Pill fill. Defaults to `foreground`. */
  pillColor?: string;
  /** Pill label. Defaults to a pale tint of the field. */
  pillLabelColor?: string;
  /** Prefix ink. Defaults to `foreground`. */
  prefixColor?: string;
  /**
   * Chip fills, cycled in order. The reference runs a period-3 cycle — a card,
   * a pale tint, a saturated one — and that is what the default builds from the
   * theme. Also accepts a comma-separated string.
   */
  chipFills?: string[] | string;
  /** Chip ink. One colour on every chip, including the saturated one. */
  chipTextColor?: string;
  /** Chip hairline. Defaults to the design system's border, scaled for a
   * surface this size (`mixOklch(border, foreground, 0.28)`). */
  chipBorderColor?: string;
  /** Act-1 type weight. */
  fontWeight?: number;
  /** Act-2 type weight. Measured 400 in the reference — the chips are bigger,
   * not heavier, and bumping this is the usual way to make them look cheap. */
  chipFontWeight?: number;
  /**
   * Pill corner radius in px. Defaults to 0.229 x pill height — which is very
   * nearly shadcn's own `radius` token over a 40px control (10/40 = 0.25), so
   * the default already sits in the design system rather than beside it. Pass
   * `theme.radius` scaled to your own control size to match exactly.
   */
  pillRadius?: number;
  /** Chip corner radius in px. Defaults to 0.162 x chip height. */
  chipRadius?: number;
  /** Chip hairline width in px. Defaults to 0.017 x chip height. */
  chipBorderWidth?: number;
  /** Pill centre, as a fraction of frame height. The reference rides 1.6% low. */
  pillCenterY?: number;
  /** Curve and timing overrides. Merged over {@link STATUS_CYCLE_MOTION}. */
  motion?: Partial<StatusCycleMotion>;
  /** Act-1 type size in px. Defaults to 8.7% of the composition height. */
  fontSize?: number;
  /** Act-2 type size in px. Defaults to 22.2% of the composition height. */
  chipFontSize?: number;
  /** Font stack. Defaults to Inter, loaded through `@remotion/google-fonts`. */
  fontFamily?: string;
  /**
   * Frames from one status swap to the next. Keep it above the roll (0.5s, 15
   * frames at 30fps) plus time to read the label: at or below the roll, the pill
   * never rests and every label is read mid-flight.
   */
  statusHold?: number;
  /** Frames the intro cascade is given before the first swap. */
  introFrames?: number;
  /** Frames from one chip's arrival to the next. */
  chipStagger?: number;
  /** Frame the scene starts on. */
  startAt?: number;
  /** Playback rate. */
  speed?: number;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

interface Metrics {
  /** Left offset and width of every prefix glyph, in layout px. */
  letters: { left: number; width: number }[];
  prefixWidth: number;
  /** Distance from the prefix box's top to its baseline. */
  baseline: number;
  statusWidths: number[];
  chipWidths: number[];
}

function StatusCycleScene({
  prefix = "Acme is",
  statuses = "designing, building, shipping, live",
  chips = "onboarding, dashboard, checkout, billing, reports",
  fieldColor,
  pageColor,
  pillColor,
  pillLabelColor,
  prefixColor,
  chipFills,
  chipTextColor,
  chipBorderColor,
  fontWeight = 400,
  chipFontWeight = 400,
  pillRadius,
  chipRadius,
  chipBorderWidth,
  pillCenterY = 0.516,
  motion,
  fontSize,
  chipFontSize,
  fontFamily,
  statusHold = 30,
  introFrames = 24,
  chipStagger = 8,
  startAt = 0,
  speed = 1,
  theme,
  mode,
}: StatusCycleProps) {
  const frame = useCurrentFrame() * speed - startAt;
  const { fps, width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS;

  // Memoised because they are `useEffect` dependencies: rebuilt every render,
  // the measuring effect would re-run forever.
  const labels = useMemo(() => toList(statuses), [statuses]);
  const chipLabels = useMemo(() => toList(chips), [chips]);
  const glyphs = useMemo(() => [...prefix], [prefix]);

  const field = fieldColor ?? t.primary;
  const page = pageColor ?? t.background;
  const pillFill = pillColor ?? t.foreground;
  const prefixInk = prefixColor ?? t.foreground;
  // A pale tint of the field: the reference's label is its own brand colour
  // lightened, and this reproduces that relationship in whatever palette the
  // component lands in.
  //
  // Mixed toward `card`, NOT `background`, and that is load-bearing. `mixOklch`
  // interpolates hue the short way round, and `background` (#faf9f6) is a *warm*
  // off-white with a real hue near 90 degrees — so a mix from a 264-degree blue
  // sweeps 174 degrees through green and lands on rgb(164,213,180). `card` is
  // achromatic, its hue is undefined, and the blue's hue is carried through
  // unchanged: rgb(178,205,247), the pale blue anyone would expect.
  const labelInk = pillLabelColor ?? mixOklch(field, t.card, 0.62);
  const chipInk = chipTextColor ?? t.foreground;
  // One hairline on every chip, from the system's own recipe for scaling a
  // border token up to a surface this size (design-system rule 3b) — not a
  // per-fill blend, because the reference likewise inks every chip the same.
  const chipEdge = chipBorderColor ?? mixOklch(t.border, t.foreground, 0.28);
  const m = { ...STATUS_CYCLE_MOTION, ...motion };
  const fills = toList(chipFills);
  const fillCycle =
    fills.length > 0 ? fills : [t.card, mixOklch(t.card, field, 0.14), field];

  const nominalEm = fontSize ?? ACT1_EM * height;
  const nominalChipEm = chipFontSize ?? ACT2_EM * height;

  // -------------------------------------------------------------------------
  // Measure. `offsetWidth`/`offsetLeft` are layout px, untouched by the
  // transforms this scene is about to apply, which is exactly what makes them
  // the right tool. Measured in a hidden, untransformed copy so frame 0 can
  // never be captured against the wrong geometry.
  // -------------------------------------------------------------------------
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("status-cycle: measuring"));
  const letterRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const prefixRef = useRef<HTMLSpanElement | null>(null);
  const baselineRef = useRef<HTMLSpanElement | null>(null);
  const statusRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const chipRefs = useRef<(HTMLSpanElement | null)[]>([]);

  useEffect(() => {
    if (metrics) {
      continueRender(handle);
      return;
    }
    const prefixWidth = prefixRef.current?.offsetWidth ?? 0;
    if (prefixWidth <= 0) return;
    setMetrics({
      letters: glyphs.map((_, i) => ({
        left: letterRefs.current[i]?.offsetLeft ?? 0,
        width: letterRefs.current[i]?.offsetWidth ?? 0,
      })),
      prefixWidth,
      baseline: baselineRef.current?.offsetTop ?? 0,
      statusWidths: labels.map(
        (_, i) => statusRefs.current[i]?.offsetWidth ?? 0,
      ),
      chipWidths: chipLabels.map(
        (_, i) => chipRefs.current[i]?.offsetWidth ?? 0,
      ),
    });
  }, [metrics, handle, glyphs, labels, chipLabels]);

  // -------------------------------------------------------------------------
  // Timeline
  // -------------------------------------------------------------------------
  const swapAt = (i: number) => introFrames + (i - 1) * statusHold;
  const act1End = swapAt(labels.length) + statusHold;
  const fadeStart = act1End;
  const fadeFrames = m.fadeSeconds * fps;
  // The three events are one beat, not three. In the reference the lockup leaves
  // and the first chip arrives on the same frame, and that frame is the exact
  // midpoint of the crossfade — colour starts moving, the swap happens under it,
  // colour finishes. Splitting them reads as three separate cuts.
  const beat = fadeStart + fadeFrames / 2;

  // Two opaque layers with an opacity ramp, not `mixOklch` between the two.
  // The reference's own crossfade does look like an OKLCH mix — its R channel
  // runs 2-5 points behind G and B, which an sRGB lerp cannot do — but its two
  // colours are a green and a cream, 30 degrees of hue apart. Ours are whatever
  // the theme says, and `primary` to `background` is 174 degrees, which OKLCH
  // walks the short way *through green*. A layered crossfade is what the word
  // means and it cannot swing.
  const fadeP = interpolate(
    frame,
    [fadeStart, fadeStart + fadeFrames],
    [0, 1],
    CLAMP,
  );

  // -------------------------------------------------------------------------
  // Fit
  //
  // A size measured off one sentence is a size that clips the next one. Both
  // acts are measured at their nominal type size and then scaled down — never
  // up — by however much the widest line overruns its share of the frame. Text
  // width is linear in font size, so the measured widths scale with the same
  // factor and no second measuring pass is needed.
  // -------------------------------------------------------------------------
  const rawPad = PILL_PAD * PILL_H * nominalEm;
  const rawGap = PILL_GAP * PILL_H * nominalEm;
  const rawLockup =
    (metrics?.prefixWidth ?? 0) +
    rawGap +
    Math.max(0, ...(metrics?.statusWidths ?? [0])) +
    2 * rawPad;
  const act1Fit = metrics ? fitScale(rawLockup, ACT1_FIT * width) : 1;

  const rawChip =
    Math.max(0, ...(metrics?.chipWidths ?? [0])) +
    2 * CHIP_PAD_X * nominalChipEm;
  const chipFit = metrics ? fitScale(rawChip, (1 - 2 * CHIP_INSET) * width) : 1;

  const em = nominalEm * act1Fit;
  const chipEm = nominalChipEm * chipFit;
  const pillH = PILL_H * em;
  const pillPad = PILL_PAD * pillH;
  const gap = PILL_GAP * pillH;
  const prefixWidth = (metrics?.prefixWidth ?? 0) * act1Fit;

  const pillWidths = (metrics?.statusWidths ?? labels.map(() => 0)).map(
    (w) => w * act1Fit + 2 * pillPad,
  );

  /** Which label is up, and how far the swap into it has progressed. */
  const widthSeconds = m.widthSeconds * fps;
  const rollSeconds = m.rollSeconds * fps;
  const { index, since } = statusAt({
    frame,
    introFrames,
    statusHold,
    count: labels.length,
  });
  // Index 0 opens from nothing rather than cutting in at full width. The tape
  // cannot settle this — its first recorded frame already has a pill, and the
  // reference's own calling->typing morph is arithmetically inseparable from
  // the intro's tail — so this runs the same curve the other morphs run, over
  // the intro, which is the least invented thing available.
  const widthP =
    index === 0
      ? m.widthEase(Math.min(1, Math.max(0, frame / introFrames)))
      : m.widthEase(Math.min(1, Math.max(0, since / widthSeconds)));
  const rollP =
    index === 0 ? 1 : m.rollEase(Math.min(1, Math.max(0, since / rollSeconds)));

  const pillW = interpolate(
    widthP,
    [0, 1],
    [index === 0 ? 0 : (pillWidths[index - 1] ?? 0), pillWidths[index] ?? 0],
  );

  // The whole lockup arrives on one slow scale settle. The reference's is still
  // drifting -7% two seconds in; this one lands, because a settle nobody can see
  // is frames spent on travel that only costs sharpness.
  const groupScale = spring({
    frame,
    fps,
    config: { damping: 26, stiffness: 90, mass: 1.4 },
    from: 1.16,
    to: 1,
  });

  const exitP = settle((frame - beat) * (1 / m.exitSeconds / fps), 0.28);
  const exitY = frame < beat ? 0 : -exitP * 0.62 * height;

  const total = prefixWidth + gap + pillW;
  const originX = (width - total) / 2;
  const cy = pillCenterY * height;

  // Only the Player gets `will-change`: a render is spread across parallel tabs
  // and each inherits a stale raster, so the same style comes out as several
  // different rasterisations and the type shimmers while standing still.
  const promote = getRemotionEnvironment().isRendering
    ? null
    : ({ willChange: "transform" } as const);

  const typeStyle = {
    fontFamily: face,
    fontWeight,
    // Hinting re-snaps every stem as the size slides, so the letterforms boil.
    // Off, shape drift over a scale falls from 3.41% to 0.22%.
    textRendering: "geometricPrecision" as const,
    whiteSpace: "nowrap" as const,
  };

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ backgroundColor: page, overflow: "hidden" }}
    >
      <AbsoluteFill
        showInTimeline={false}
        style={{ backgroundColor: field, opacity: 1 - fadeP }}
      />
      {metrics ? null : (
        <Measuring
          glyphs={glyphs}
          labels={labels}
          chipLabels={chipLabels}
          em={em}
          chipEm={chipEm}
          typeStyle={typeStyle}
          letterRefs={letterRefs}
          prefixRef={prefixRef}
          baselineRef={baselineRef}
          statusRefs={statusRefs}
          chipRefs={chipRefs}
        />
      )}

      {metrics && frame < beat + m.exitSeconds * fps ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            transform: `translateY(${exitY}px) scale(${groupScale})`,
            transformOrigin: `${width / 2}px ${cy}px`,
            width,
            height,
            ...promote,
          }}
        >
          <Prefix
            glyphs={glyphs}
            metrics={metrics}
            frame={frame}
            fps={fps}
            em={em}
            fit={act1Fit}
            spring={m.letterSpring}
            stagger={m.letterStagger}
            x={originX}
            cy={cy}
            color={prefixInk}
            typeStyle={typeStyle}
          />
          <Pill
            labels={labels}
            index={index}
            rollP={rollP}
            x={originX + prefixWidth + gap}
            cy={cy}
            width={pillW}
            height={pillH}
            em={em}
            fill={pillFill}
            ink={labelInk}
            radius={pillRadius ?? PILL_R * pillH}
            travel={m.rollTravel * pillH}
            typeStyle={typeStyle}
          />
        </div>
      ) : null}

      {metrics ? (
        <Chips
          labels={chipLabels}
          widths={metrics.chipWidths.map((w) => w * chipFit)}
          frame={frame}
          fps={fps}
          beat={beat}
          stagger={chipStagger}
          em={chipEm}
          width={width}
          height={height}
          fills={fillCycle}
          ink={chipInk}
          edge={chipEdge}
          radius={chipRadius}
          borderWidth={chipBorderWidth}
          weight={chipFontWeight}
          tau={m.scrollTau}
          typeStyle={typeStyle}
        />
      ) : null}
    </AbsoluteFill>
  );
}

/**
 * The intro cascade: every glyph sits at its **final advance** and scales about
 * its own baseline, staggered left to right.
 *
 * Measured, not guessed. Tracking one 'o' by its counter gives 1.01x → 1.45x →
 * 1.00x while its stroke-to-height ratio holds at 0.149 ± 0.006 — so nothing is
 * animating a weight or width axis, it is a plain scale, and the letters only
 * *look* heavier early because at 1.45x they overlap their neighbours' fixed
 * slots. The prefix's total ink span is unchanged from the first frame to the
 * last, which is only possible if the layout is static and the transform is
 * per-glyph.
 *
 * The one deliberate departure from the reference is the pivot. The reference
 * scales each letter about its centre, which drags the baseline; a moving
 * baseline climbs the pixel grid in whole-pixel jumps, because the rasteriser
 * has no vertical sub-pixel positioning at all. Pivoting on the baseline takes
 * judder from 0.284px to 0.014px and direction reversals from 29 to 0, and it
 * costs a downward growth nobody can name.
 */
function Prefix({
  glyphs,
  metrics,
  frame,
  fps,
  em,
  fit,
  spring: springConfig,
  stagger,
  x,
  cy,
  color,
  typeStyle,
}: {
  glyphs: string[];
  metrics: Metrics;
  frame: number;
  fps: number;
  em: number;
  /** Scale the measured glyph offsets were taken at, relative to `em`. */
  fit: number;
  spring: { damping: number; stiffness: number; mass: number };
  stagger: number;
  x: number;
  cy: number;
  color: string;
  typeStyle: React.CSSProperties;
}) {
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: cy - em,
        height: 2 * em,
        color,
        fontSize: em,
        lineHeight: 2,
        ...typeStyle,
      }}
    >
      {glyphs.map((g, i) => {
        // Stagger of one frame. Measured: the shared scale curve takes about one
        // 30fps frame to travel 0.71x → 1.01x, which is the gap the reference
        // shows between adjacent letters.
        const p = spring({
          frame: frame - i * stagger,
          fps,
          config: springConfig,
        });
        // The spring carries the overshoot; `interpolate` extrapolates past 1,
        // so mapping [0,1] onto [0.1,1] puts the peak at 1.4x on its own — no
        // second curve, and nothing to keep in step with the damping.
        const s = interpolate(p, [0, 1], [0.1, 1]);
        return (
          <span
            // biome-ignore lint/suspicious/noArrayIndexKey: positional glyph slot
            key={i}
            style={{
              position: "absolute",
              left: (metrics.letters[i]?.left ?? 0) * fit,
              top: 0,
              transform: `scale(${s})`,
              transformOrigin: `50% ${metrics.baseline * fit}px`,
              ...typeStyle,
            }}
          >
            {g === " " ? " " : g}
          </span>
        );
      })}
    </div>
  );
}

/**
 * The pill: a width that animates straight through a label that never changes
 * size, and two stacked labels rolling upward behind a hard clip.
 *
 * The label is laid out at its full final width and centred, and the widening
 * pill reveals it from the middle out — proven on the reference by the two
 * inter-word gaps of "sharing a moment" sitting at x = 486.0 and 521.5 across
 * three frames while the pill grew 83px. So the width cannot be derived from a
 * padded text box each frame; it is its own animated quantity.
 *
 * There is no crossfade. The label ink's mean brightness holds inside a 4% band
 * through every swap, including the frames where both labels are half-clipped —
 * a fade would collapse it toward the fill. Pure translation plus clipping.
 */
function Pill({
  labels,
  index,
  rollP,
  x,
  cy,
  width,
  height,
  em,
  fill,
  ink,
  radius,
  travel,
  typeStyle,
}: {
  labels: string[];
  index: number;
  rollP: number;
  x: number;
  cy: number;
  width: number;
  height: number;
  em: number;
  fill: string;
  ink: string;
  radius: number;
  travel: number;
  typeStyle: React.CSSProperties;
}) {
  const showOutgoing = rollP < 1 && index > 0;

  const label = (text: string, offset: number) => (
    <div
      style={{
        position: "absolute",
        left: "50%",
        top: 0,
        height,
        display: "flex",
        alignItems: "center",
        transform: `translate(-50%, ${offset}px)`,
        color: ink,
        fontSize: em,
        ...typeStyle,
      }}
    >
      {text}
    </div>
  );

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: cy - height / 2,
        width,
        height,
        borderRadius: radius,
        backgroundColor: fill,
        overflow: "hidden",
      }}
    >
      {showOutgoing ? label(labels[index - 1] ?? "", -rollP * travel) : null}
      {label(labels[index] ?? "", (1 - rollP) * travel)}
    </div>
  );
}

/**
 * Act 2: chips ride a field that steps, not scrolls.
 *
 * The field is dead still between beats — residual velocity under 1px per
 * captured frame — and then jumps exactly one slot with a hard ease-out on the
 * frame a new chip appears. The chips themselves do nothing: measured across
 * every frame each is visible, width and fill are final from the first frame and
 * never change, and two chips in the same step travelled 140.02px and 139.34px,
 * so it is one transform on the container rather than per-chip animation.
 */
function Chips({
  labels,
  widths,
  frame,
  fps,
  beat,
  stagger,
  em,
  width,
  height,
  fills,
  ink,
  edge,
  radius,
  borderWidth,
  weight,
  tau: scrollTau,
  typeStyle,
}: {
  labels: string[];
  widths: number[];
  frame: number;
  fps: number;
  beat: number;
  stagger: number;
  em: number;
  width: number;
  height: number;
  fills: string[];
  ink: string;
  edge: string;
  radius?: number;
  borderWidth?: number;
  weight: number;
  tau: number;
  typeStyle: React.CSSProperties;
}) {
  if (frame < beat) return null;

  const chipH = em * (1 + 2 * CHIP_PAD_Y);
  const step = chipH + CHIP_GAP * height;
  const tau = scrollTau * fps;

  // How many chips have arrived, and how far the current step has run.
  const { arrived, since } = chipAt({
    frame,
    beat,
    stagger,
    count: labels.length,
  });
  const p = settle(since, tau);
  // The newest chip comes to rest one gap clear of the bottom edge. Landing it
  // flush reads as clipped rather than as arrived — its border sits on the
  // frame edge and half of it is lost to the codec.
  const fieldY = height - CHIP_GAP * height - chipH - (arrived - 2 + p) * step;

  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden" }}>
      {labels.slice(0, arrived).map((text, i) => {
        const w = (widths[i] ?? 0) + 2 * CHIP_PAD_X * em;
        const left = i % 2 === 0;
        const fill = fills[i % fills.length] ?? fills[0];
        return (
          // biome-ignore lint/suspicious/noArrayIndexKey: positional chip slot
          <Item key={i} index={i}>
            <div
              style={{
                position: "absolute",
                top: 0,
                left: left ? CHIP_INSET * width : undefined,
                right: left ? undefined : CHIP_INSET * width,
                transform: `translateY(${fieldY + i * step}px)`,
                width: w,
                height: chipH,
                borderRadius: radius ?? CHIP_R * chipH,
                backgroundColor: fill,
                // A hairline and nothing else. The reference has no shadow — cream
                // measured through a chip's top edge recovers to its flat value
                // within 2px on both sides, with no directional darkening — and a
                // drop shadow under a light chip on a light page is a grey smear.
                border: `${borderWidth ?? CHIP_BORDER * chipH}px solid ${edge}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: ink,
                fontSize: em,
                ...typeStyle,
                fontWeight: weight,
              }}
            >
              {text}
            </div>
          </Item>
        );
      })}
    </div>
  );
}

/**
 * The hidden, untransformed copy every measurement is taken from. Rendered only
 * until `metrics` exists, and `delayRender` holds frame 0 until then.
 */
function Measuring({
  glyphs,
  labels,
  chipLabels,
  em,
  chipEm,
  typeStyle,
  letterRefs,
  prefixRef,
  baselineRef,
  statusRefs,
  chipRefs,
}: {
  glyphs: string[];
  labels: string[];
  chipLabels: string[];
  em: number;
  chipEm: number;
  typeStyle: React.CSSProperties;
  // Plain `{ current }` shapes, not RefObject: React 18's RefObject is
  // read-only and rejects what `useRef(null)` hands back in a React 19 project.
  letterRefs: { current: (HTMLSpanElement | null)[] };
  prefixRef: { current: HTMLSpanElement | null };
  baselineRef: { current: HTMLSpanElement | null };
  statusRefs: { current: (HTMLSpanElement | null)[] };
  chipRefs: { current: (HTMLSpanElement | null)[] };
}) {
  return (
    <div
      aria-hidden
      style={{
        position: "absolute",
        visibility: "hidden",
        left: 0,
        top: 0,
        pointerEvents: "none",
        // Each measured span is `inline-block` and gets its own line, so it
        // reports its own text width. Left as blocks they fill this
        // shrink-to-fit box and every label comes back the widest one's width —
        // which is four identical pills and a prefix pushed off the frame.
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
      }}
    >
      <span
        ref={prefixRef}
        style={{ fontSize: em, lineHeight: 2, ...typeStyle }}
      >
        {glyphs.map((g, i) => (
          <span
            // biome-ignore lint/suspicious/noArrayIndexKey: positional glyph slot
            key={i}
            ref={(el) => {
              letterRefs.current[i] = el;
            }}
            style={{ display: "inline-block" }}
          >
            {g === " " ? " " : g}
          </span>
        ))}
        {/* A zero-sized inline-block sits ON the baseline, so `offsetTop` reads
            it rather than a line-height ratio anyone has to guess. */}
        <span
          ref={baselineRef}
          style={{ display: "inline-block", width: 0, height: 0 }}
        />
      </span>
      {labels.map((text, i) => (
        <span
          // biome-ignore lint/suspicious/noArrayIndexKey: positional label slot
          key={i}
          ref={(el) => {
            statusRefs.current[i] = el;
          }}
          style={{ display: "inline-block", fontSize: em, ...typeStyle }}
        >
          {text}
        </span>
      ))}
      {chipLabels.map((text, i) => (
        <span
          // biome-ignore lint/suspicious/noArrayIndexKey: positional chip slot
          key={i}
          ref={(el) => {
            chipRefs.current[i] = el;
          }}
          style={{ display: "inline-block", fontSize: chipEm, ...typeStyle }}
        >
          {text}
        </span>
      ))}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one chip at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function StatusCyclePainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}

/** Whether every box that clips `el`, up to `root`, leaves all of it showing. */
function StatusCycleWhole(el: Element, root: Element): boolean {
  const r = el.getBoundingClientRect();
  for (let a = el.parentElement; a; a = a === root ? null : a.parentElement) {
    if (getComputedStyle(a).overflow === "visible") continue;
    const c = a.getBoundingClientRect();
    if (
      r.left < c.left - 1 ||
      r.top < c.top - 1 ||
      r.right > c.right + 1 ||
      r.bottom > c.bottom + 1
    )
      return false;
  }
  return true;
}
type StatusCycleChipValues = {
  readonly label?: string;
};

type StatusCycleChipProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  StatusCycleChipValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this chip as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: StatusCycleChipState) => void;
  };

/** What Studio is doing to one chip right now, which the stage applies to its node. */
type StatusCycleChipState = {
  values: StatusCycleChipValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const StatusCycleChipSchema = {
  ...Interactive.baseSchema,
  label: { type: "text-content", default: "", description: "Label" },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One chip: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the chip is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const StatusCycleChipInner = forwardRef<
  Element,
  StatusCycleChipProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      label,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it or it paints past its own box; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { label },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? StatusCyclePainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const n = el.getBoundingClientRect();
      if (
        StatusCycleWhole(el, root) &&
        b[0] >= n.left - 1 &&
        b[1] >= n.top - 1 &&
        b[2] <= n.right + 1 &&
        b[3] <= n.bottom + 1
      ) {
        box.style.display = "none";
        target.current = el;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Chip"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const StatusCycleChip = Interactive.withSchema({
  Component: StatusCycleChipInner,
  componentName: "<StatusCycleChip>",
  schema: StatusCycleChipSchema,
  supportsEffects: false,
});

type StatusCycleStageProps = InteractiveBaseProps &
  Omit<ComponentProps<typeof StatusCycleScene>, "chips"> & {
    readonly children?: ReactNode;
  };

/**
 * What a scene prop falls back to when Studio does not pass it, reset included.
 * The chips' own lists are here only for the scene's parameter defaults;
 * the stage always passes the ones its children build.
 */
const StatusCycleDefaults = {
  prefix: "Acme is",
  statuses: "designing, building, shipping, live",
  chips: "onboarding, dashboard, checkout, billing, reports",
  fieldColor: "transparent",
  pageColor: "transparent",
  pillColor: "#141414",
  pillLabelColor: "rgb(178, 205, 247)",
  prefixColor: "#141414",
  chipFills: "#ffffff, rgb(226, 236, 253), #3577e0",
  chipTextColor: "#141414",
  chipBorderColor: "rgb(160, 160, 160)",
  fontWeight: 400,
  chipFontWeight: 400,
  fontSize: 63,
  chipFontSize: 160,
  introFrames: 24,
  statusHold: 30,
  chipStagger: 8,
  pillCenterY: 0.516,
  startAt: 0,
  speed: 1,
} satisfies Partial<StatusCycleStageProps> &
  Partial<Pick<ComponentProps<typeof StatusCycleScene>, "chips">>;

const StatusCycleStageSchema = {
  ...Interactive.baseSchema,
  prefix: { type: "text-content", default: "Acme is", description: "Prefix" },
  statuses: {
    type: "text-content",
    default: "designing, building, shipping, live",
    description: "Statuses (comma-separated)",
  },
  fieldColor: {
    type: "color",
    default: "transparent",
    description: "Field (act 1)",
    keyframable: false,
  },
  pillColor: {
    type: "color",
    default: "#141414",
    description: "Pill",
    keyframable: false,
  },
  pillLabelColor: {
    type: "color",
    default: "rgb(178, 205, 247)",
    description: "Pill label",
    keyframable: false,
  },
  prefixColor: {
    type: "color",
    default: "#141414",
    description: "Prefix ink",
    keyframable: false,
  },
  chipTextColor: {
    type: "color",
    default: "#141414",
    description: "Chip ink",
    keyframable: false,
  },
  chipBorderColor: {
    type: "color",
    default: "rgb(160, 160, 160)",
    description: "Chip hairline",
    keyframable: false,
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 1,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * A value as the scene's list will read it back: each separator it would split
 * on becomes a character that looks the same and does not split, so "Hello,
 * world" stays one chip and the ones after it keep their outlines.
 */
function StatusCycleClean(v: string | undefined, seps: string): string {
  const look: Record<string, string> = {
    ",": "\u201A",
    "|": "\u2223",
    ";": "\u037E",
    ">": "\u203A",
  };
  let out = v ?? "";
  for (const c of seps.split(" ").join(""))
    out = out.split(c).join(look[c] ?? " ");
  return out;
}

/** The scene's props, from its chips' values in order. */
const StatusCycleFromItems = (o: readonly StatusCycleChipValues[]) => ({
  chips: o.map((x) => StatusCycleClean(x.label, ", ")).join(", "),
});

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function StatusCycleFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

/** The host, told the frame inside the Element — the one its layers' timing is in. */
function StatusCycleHosted({
  host,
  children,
}: {
  host: (frame: number) => ItemHost;
  children: ReactNode;
}) {
  return (
    <ItemHostProvider value={host(useCurrentFrame())}>
      {children}
    </ItemHostProvider>
  );
}

/**
 * The scene, with its chips as children. It reads their values to lay
 * the scene out, and hands each one back the node the scene draws it as.
 */
const StatusCycleStageInner = forwardRef<
  HTMLDivElement,
  StatusCycleStageProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      children,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    // One empty box per chip on the stage: the outline it falls back to,
    // which it moves over the part of itself that shows.
    const slots = useRef<{ current: HTMLDivElement | null }[]>([]);
    const slotFor = (i: number) => {
      slots.current[i] ??= { current: null };
      return slots.current[i];
    };
    // Every chip the file lists, by position: each keeps its layer.
    const all = Children.toArray(children).filter(
      isValidElement,
    ) as ReactElement<StatusCycleChipProps>[];
    const claims = useRef<{ current: Element | null }[]>([]);
    const claimFor = (j: number) => {
      claims.current[j] ??= { current: null };
      return claims.current[j];
    };
    const rest = { ...StatusCycleDefaults, ...props };
    // What Studio is doing to each chip that the file may not have yet.
    const [live, setLive] = useState<Record<number, StatusCycleChipState>>({});
    const report = (j: number, state: StatusCycleChipState) =>
      setLive((prev) =>
        JSON.stringify(prev[j]) === JSON.stringify(state)
          ? prev
          : { ...prev, [j]: state },
      );
    const merged = all.map((o, j) => {
      const st = live[j];
      return st
        ? {
            ...o.props,
            ...st.values,
            style: st.style,
            hidden: st.hidden,
            from: st.from,
            durationInFrames: st.durationInFrames,
          }
        : o.props;
    });
    // The ones the scene draws, in its order: the positions its `Item`s index.
    const kept = all
      .map((_, j) => j)
      .filter((j) =>
        ((x: StatusCycleChipValues) => Boolean(x.label?.trim()))(
          merged[j] as StatusCycleChipValues,
        ),
      );
    const built = StatusCycleFromItems(
      kept.map((j) => merged[j] as StatusCycleChipValues),
    );
    const host =
      (frame: number): ItemHost =>
      (index, node) => {
        const j = kept[index];
        const m = j === undefined ? undefined : merged[j];
        if (j === undefined || !m) return node;
        // The layer's own visibility and timing, which its Sequence would apply
        // if it held the node.
        const start = m.from ?? 0;
        if (
          m.hidden ||
          frame < start ||
          frame >= start + (m.durationInFrames ?? Number.POSITIVE_INFINITY)
        )
          return null;
        const own = node as ReactElement<{
          ref?: Ref<Element>;
          style?: CSSProperties;
        }>;
        return cloneElement(own, {
          ref: claimFor(j),
          style: { ...own.props.style, ...m.style },
        });
      };
    // The scene measures its copy once, on mount, so a saved edit remounts it.
    // An edit still being typed does not: the scene would restart on every
    // keystroke. The layers are outside it and never remount with it.
    const key = JSON.stringify({
      ...rest,
      ...StatusCycleFromItems(
        all
          .filter((o) =>
            ((x: StatusCycleChipValues) => Boolean(x.label?.trim()))(o.props),
          )
          .map((o) => o.props),
      ),
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Status Cycle"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
          }}
        >
          {/* First, so each box's ref is set before the objects that move it
              run their layout effects on a fresh mount. */}
          {all.map((_, j) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: one box per position
              key={j}
              ref={slotFor(j)}
              style={{
                position: "absolute",
                display: "none",
                pointerEvents: "none",
                opacity: 0,
              }}
            />
          ))}
          <StatusCycleFade>
            <StatusCycleHosted host={host}>
              <StatusCycleScene key={key} {...rest} {...built} />
            </StatusCycleHosted>
          </StatusCycleFade>
          {/* The layers, after the scene: its nodes are attached by the time
              they measure them. */}
          {all.map((o, j) =>
            cloneElement(o, {
              // biome-ignore lint/suspicious/noArrayIndexKey: one layer per position
              key: j,
              claim: claimFor(j),
              slot: slotFor(j),
              report: (state: StatusCycleChipState) => report(j, state),
            }),
          )}
        </div>
      </Sequence>
    );
  },
);

const StatusCycleStage = Interactive.withSchema({
  Component: StatusCycleStageInner,
  componentName: "<StatusCycleStage>",
  schema: StatusCycleStageSchema,
  supportsEffects: false,
});

